  ) AS v(cnos, legacy, name, link, lat, lng, contact, phone)
  JOIN LATERAL (SELECT min(c."storeId") AS "storeId", min(c."customerId") AS "partyId", count(DISTINCT c."customerId") AS n
                  FROM "Complaint" c WHERE c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c."legacyRef" = ANY (string_to_array(v.cnos, '|'))) m ON m.n = 1
 WHERE NOT EXISTS (SELECT 1 FROM "PartySite" x WHERE x."partyId" = m."partyId" AND upper(x.name) = upper(v.name));

-- 2. INSURANCE POLICIES (old "Insurance Policy" screen) -> Common Hub renewals.
INSERT INTO "PolicyRenewal" (id, "storeId", title, "policyType", provider, "policyNumber", "expiryDate", "reminderDays", notes, "isActive", "createdAt", "updatedAt")
