     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), v.title, 'Insurance', v.provider, v.no, v.expiry, 30, v.notes, true, v.created, now()
  FROM (VALUES
